          if(timer_q[x]!=0 && !high_q[x]) timer_q[x]<=timer_q[x]-1'b1;
          else if(!send_ok[x]) run_active_q[x]<=0; // explicit fault, never retry
          else if(context_q[run_ctx_q[x]][114] && context_q[run_ctx_q[x]][116] && !high_q[x]) high_q[x]<=1;
          else begin
            high_q[x]<=0; pair_fill_q[x]<=0; pair_ready_q[x]<=0;
            if(remaining_q[x]==1) run_active_q[x]<=0;
            else begin
              remaining_q[x]<=remaining_q[x]-1'b1; sequence_q[x]<=sequence_q[x]+1'b1;
              timer_q[x]<=interval_q[x]-(high_q[x]?2:1);
            end
          end
        end
      end
    end
  end
`ifndef SYNTHESIS
  initial if((T!=2 && T!=4 && T!=8) || TIMER_BITS<2 || TIMER_BITS>24 || (PORT_STREAMS!=16 && PORT_STREAMS!=32))
    $fatal(1,"unsupported SXM row geometry/timer width");
`endif
endmodule
